SELECT e.name,p.prosecdef=e.definer AS exact_execution_context,p.proconfig IS NOT DISTINCT FROM CASE WHEN e.config IS NULL THEN NULL ELSE ARRAY[e.config]::text[] END AS exact_search_path FROM (VALUES ('cohort_assert_record_parent_v1',true,'search_path=pg_catalog, public, pg_temp'),('cohort_guard_completion_record_identity_v1',true,'search_path=pg_catalog, public, pg_temp'),('cohort_sync_training_session_from_terminal_record',true,'search_path=pg_catalog, public, pg_temp'),('cohort_assert_completion_request_v1',true,'search_path=pg_catalog, public, pg_temp'),('complete_programme_session_and_advance',true,'search_path=pg_catalog, public, pg_temp'),('complete_fixed_programme_occurrence_and_advance',true,'search_path=pg_catalog, public, pg_temp'),('complete_training_session_record',true,'search_path=pg_catalog, public, pg_temp'),('correct_completed_performance_record',true,'search_path=pg_catalog, public, pg_temp'),('cohort_complete_backfilled_fixed_occurrence_at',true,'search_path=pg_catalog, public, pg_temp'),('cohort_guard_direct_result_write_v1',false,'search_path=pg_catalog, public, pg_temp'),('cohort_guard_result_identity_v1',true,'search_path=pg_catalog, public, pg_temp'),('cohort_insert_training_session_result_tree',true,'search_path=public, pg_temp'),('cohort_completion_programme_body_v1',true,'search_path=public, pg_temp'),('cohort_completion_fixed_body_v1',true,'search_path=public, pg_temp'),('cohort_completion_standalone_body_v1',false,NULL),('cohort_completion_correction_body_v1',true,'search_path=public, pg_temp'),('cohort_completion_backfill_body_v1',true,'search_path=public, pg_temp'),('complete_backfilled_fixed_programme_occurrence',true,'search_path=public, pg_temp')) e(name,definer,config) LEFT JOIN pg_proc p ON p.pronamespace='public'::regnamespace AND p.proname=e.name ORDER BY e.name;
